def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def label(path):return str(path.relative_to(ROOT))
def save(path,data):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
def load(name,path):
    spec=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m
def body(path,symbol):
    text=path.read_text();node=ast.parse(text)
    for name in symbol.split('.'):
        matches=[n for n in node.body if isinstance(n,(ast.ClassDef,ast.FunctionDef)) and n.name==name];assert matches,(path,symbol);node=matches[-1]
    lines=text.splitlines(keepends=True);end=node.end_lineno
    while end<len(lines) and not lines[end].strip():end+=1
    return ''.join(lines[node.lineno-1:end]),node.lineno,end

